package bech32

import (
	"testing"
)

func TestDecodeUnicode(t *testing.T) {
	// This test should fail on the buggy implementation and pass after the fix.
	// The input contains Unicode characters that should cause a panic in the
	// original code due to improper handling of rune iteration.
	_, _, err := Decode("a1ß")
	if err == nil {
		t.Errorf("Expected error for Unicode input, got nil")
	}
}

func TestEncodeUnicode(t *testing.T) {
	// This test should fail on the buggy implementation and pass after the fix.
	// The input contains Unicode characters that should cause a panic in the
	// original code due to improper handling of rune iteration.
	_, err := Encode("a", []byte{0x01})
	if err == nil {
		t.Errorf("Expected error for Unicode HRP, got nil")
	}
}

func TestDecodeValid(t *testing.T) {
	hrp, data, err := Decode("bc1qar0srrr7xfkvy5l643lydnw9re59gtzzwf5mdq")
	if err != nil {
		t.Fatalf("Unexpected error: %v", err)
	}
	if hrp != "bc" {
		t.Errorf("Expected hrp 'bc', got '%s'", hrp)
	}
	expected := []byte{0x01, 0x02, 0x03}
	if len(data) != len(expected) {
		t.Errorf("Expected data length %d, got %d", len(expected), len(data))
	}
	for i, v := range expected {
		if data[i] != v {
			t.Errorf("Expected data[%d]=%d, got %d", i, v, data[i])
		}
	}
}

func TestEncodeDecode(t *testing.T) {
	hrp := "test"
	data := []byte{0x01, 0x02, 0x03}
	encoded, err := Encode(hrp, data)
	if err != nil {
		t.Fatalf("Unexpected error: %v", err)
	}
	decodedHrp, decodedData, err := Decode(encoded)
	if err != nil {
		t.Fatalf("Unexpected error: %v", err)
	}
	if decodedHrp != hrp {
		t.Errorf("Expected hrp '%s', got '%s'", hrp, decodedHrp)
	}
	if len(decodedData) != len(data) {
		t.Errorf("Expected data length %d, got %d", len(data), len(decodedData))
	}
	for i, v := range data {
		if decodedData[i] != v {
			t.Errorf("Expected data[%d]=%d, got %d", i, v, decodedData[i])
		}
	}
}
