Looking at the commit message, the issue is that the Accept-Language header parsing is not correctly handling quality factors in language detection. The current implementation passes the raw Accept-Language header directly to `i18n.NewLocalizer`, but it should parse the header to extract the preferred language with proper quality factor handling.

Let me examine the code and create a test that would fail with the current implementation and pass after fixing:

// file: lib/localization/localization_test.go
```go
package localization

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestGetLocalizerFromRequest(t *testing.T) {
	// Create a test request with Accept-Language header containing quality factors
	tests := []struct {
		name           string
		acceptLanguage string
		expectedLang   string
	}{
		{
			name:           "Simple language without quality",
			acceptLanguage: "en-US,en;q=0.9,fr;q=0.8",
			expectedLang:   "en-US", // Should pick the first one with highest quality
		},
		{
			name:           "Language with explicit quality 1.0",
			acceptLanguage: "fr;q=1.0,en;q=0.5",
			expectedLang:   "fr", // Should pick fr since it has quality 1.0
		},
		{
			name:           "Multiple languages with same quality",
			acceptLanguage: "en-US,en;q=0.9,fr;q=0.9",
			expectedLang:   "en-US", // Should pick first one in list
		},
		{
			name:           "No quality factors",
			acceptLanguage: "en-US,en,fr",
			expectedLang:   "en-US", // Should pick first one
		},
		{
			name:           "Empty header",
			acceptLanguage: "",
			expectedLang:   "en", // Should fallback to default
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req := httptest.NewRequest("GET", "/", nil)
			req.Header.Set("Accept-Language", tt.acceptLanguage)

			// Create a localization service with some test locales
			service := NewLocalizationService()

			// This should not panic and should return a valid localizer
			localizer := service.GetLocalizerFromRequest(req)

			// Verify that we can at least call a simple localize function
			assert.NotNil(t, localizer)
		})
	}
}

func TestGetLocalizerQualityFactors(t *testing.T) {
	// Test that quality factors are properly considered
	req := httptest.NewRequest("GET", "/", nil)

	// Set up a request with quality factors that should result in specific language selection
	req.Header.Set("Accept-Language", "fr;q=0.9,en;q=0.8,de;q=0.7")

	service := NewLocalizationService()
	localizer := service.GetLocalizerFromRequest(req)

	// The localizer should be created without error
	assert.NotNil(t, localizer)

	// Test with a request that has no quality factors
	req2 := httptest.NewRequest("GET", "/", nil)
	req2.Header.Set("Accept-Language", "en-US,en")

	localizer2 := service.GetLocalizerFromRequest(req2)
	assert.NotNil(t, localizer2)
}
