The issue is in the `splitIndexesToChunks` function where it modifies `idx[0]` but this change doesn't persist correctly through the loop iterations, and the logic for handling multi-chunk matches is flawed.

Let me create a test file that would fail with the current implementation:

// file: main_test.go
```go
package main

import (
	"testing"
)

func TestSplitIndexesToChunks(t *testing.T) {
	// Test case where a search index spans multiple chunks
	chunks := [][]byte{
		[]byte("hello "),
		[]byte("world"),
		[]byte(" test"),
	}
	indexes := [][]int{{0, 11}} // This spans across chunks

	result := splitIndexesToChunks(chunks, indexes, 0)

	// The expected behavior is that the index [0,11] should be split
	// between the chunks: [0,6] in first chunk, [0,5] in second chunk, [0,1] in third chunk
	if len(result) != 3 {
		t.Errorf("Expected 3 chunks, got %d", len(result))
	}

	// Check that we have matches in the right chunks
	if len(result[0]) != 1 || result[0][0].start != 0 || result[0][0].end != 6 {
		t.Errorf("First chunk match incorrect: %v", result[0])
	}

	if len(result[1]) != 1 || result[1][0].start != 0 || result[1][0].end != 5 {
		t.Errorf("Second chunk match incorrect: %v", result[1])
	}

	if len(result[2]) != 1 || result[2][0].start != 0 || result[2][0].end != 1 {
		t.Errorf("Third chunk match incorrect: %v", result[2])
	}
}

func TestSplitIndexesToChunksSingleChunk(t *testing.T) {
	chunks := [][]byte{
		[]byte("hello world"),
	}
	indexes := [][]int{{0, 5}} // This fits entirely in the first chunk

	result := splitIndexesToChunks(chunks, indexes, 0)

	if len(result) != 1 {
		t.Errorf("Expected 1 chunk, got %d", len(result))
	}

	if len(result[0]) != 1 || result[0][0].start != 0 || result[0][0].end != 5 {
		t.Errorf("Single chunk match incorrect: %v", result[0])
	}
}

func TestSplitIndexesToChunksNoMatch(t *testing.T) {
	chunks := [][]byte{
		[]byte("hello "),
		[]byte("world"),
	}
	indexes := [][]int{{100, 105}} // This is outside the bounds

	result := splitIndexesToChunks(chunks, indexes, 0)

	if len(result) != 2 {
		t.Errorf("Expected 2 chunks, got %d", len(result))
	}

	for i, chunk := range result {
		if len(chunk) != 0 {
			t.Errorf("Chunk %d should be empty, got %v", i, chunk)
		}
	}
}
