package externalcmd

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestCmdRunOSSpecific(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("skipping on windows")
	}

	t.Run("successful command", func(t *testing.T) {
		c := &Cmd{
			Env: map[string]string{},
		}

		err := c.Run("echo hello")
		assert.NoError(t, err)
	})

	t.Run("failed command with exit code", func(t *testing.T) {
		c := &Cmd{
			Env: map[string]string{},
		}

		// Use a command that will definitely fail with a non-zero exit code
		err := c.Run("false")
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "command exited with code 1")
	})

	t.Run("failed command with exit code 2", func(t *testing.T) {
		c := &Cmd{
			Env: map[string]string{},
		}

		// Use a command that will definitely fail with exit code 2
		err := c.Run("sh -c 'exit 2'")
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "command exited with code 2")
	})

	t.Run("command with environment variables", func(t *testing.T) {
		c := &Cmd{
			Env: map[string]string{
				"TEST_VAR": "test_value",
			},
		}

		err := c.Run("sh -c 'echo $TEST_VAR'")
		assert.NoError(t, err)
	})

	t.Run("command that doesn't exist", func(t *testing.T) {
		c := &Cmd{
			Env: map[string]string{},
		}

		err := c.Run("this_command_does_not_exist_12345")
		assert.Error(t, err)
	})
}

func TestCmdRunOSSpecificIntegration(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("skipping on windows")
	}

	t.Run("exit code 1", func(t *testing.T) {
		c := &Cmd{
			Env: map[string]string{},
		}

		err := c.Run("sh -c 'exit 1'")
		require.Error(t, err)
		assert.Contains(t, err.Error(), "command exited with code 1")
	})

	t.Run("exit code 42", func(t *testing.T) {
		c := &Cmd{
			Env: map[string]string{},
		}

		err := c.Run("sh -c 'exit 42'")
		require.Error(t, err)
		assert.Contains(t, err.Error(), "command exited with code 42")
	})
}

func TestCmdRunOSSpecificWithTermination(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("skipping on windows")
	}

	t.Run("terminated command", func(t *testing.T) {
		c := &Cmd{
			Env: map[string]string{},
		}

		// This should be terminated by the timeout
		done := make(chan error)
		go func() {
			err := c.Run("sleep 10")
			done <- err
		}()

		// Give it a moment to start
		time.Sleep(10 * time.Millisecond)

		// Cancel the command
		c.Cancel()

		select {
		case err := <-done:
			assert.Error(t, err)
			assert.Contains(t, err.Error(), "terminated")
		case <-time.After(5 * time.Second):
			t.Fatal("command did not terminate in time")
		}
	})
}

func TestCmdRunOSSpecificExitCodeExtraction(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("skipping on windows")
	}

	// This test verifies that the exit code is properly extracted from ExitError
	c := &Cmd{
		Env: map[string]string{},
	}

	// Test with a command that exits with code 123
	err := c.Run("sh -c 'exit 123'")
	require.Error(t, err)

	// The error should contain the exit code
	assert.Contains(t, err.Error(), "command exited with code 123")

	// Test with a command that exits with code 0 (should succeed)
	err = c.Run("sh -c 'exit 0'")
	assert.NoError(t, err)
}
