func TestNewConfForeignArchNetworkAddress(t *testing.T) {
	// Test that when using a foreign architecture with network address enabled,
	// the configuration properly handles the network setup even when vz and krunkit
	// are not available for foreign arch
	tests := []struct {
		name           string
		arch           string
		vmType         limaconfig.VMType
		networkAddress bool
		expectNetwork  bool
	}{
		{
			name:           "foreign arch with vz and network address",
			arch:           "amd64",
			vmType:         limaconfig.VZ,
			networkAddress: true,
			expectNetwork:  false, // Should fallback to qemu, so no network setup
		},
		{
			name:           "foreign arch with krunkit and network address",
			arch:           "amd64",
			vmType:         limaconfig.Krunkit,
			networkAddress: true,
			expectNetwork:  false, // Should fallback to qemu, so no network setup
		},
		{
			name:           "foreign arch with qemu and network address",
			arch:           "amd64",
			vmType:         limaconfig.QEMU,
			networkAddress: true,
			expectNetwork:  true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			ctx := context.Background()
			conf := config.Config{
				Arch:           tt.arch,
				VMType:         tt.vmType,
				Network:        config.Network{Address: tt.networkAddress},
			}

			// This should not panic or fail when network address is enabled
			// for foreign architectures
			l, err := newConf(ctx, conf)
			assert.NoError(t, err)

			// Check that network configuration is handled properly
			if tt.expectNetwork {
				// Should have at least one network configured
				assert.NotEmpty(t, l.Networks)
			} else {
				// For foreign arch with vz/krunkit, should fallback to qemu
				// and potentially not configure network if not needed
				assert.NotNil(t, l.Networks)
			}
		})
	}
}

func TestNewConfNetworkAddressFallback(t *testing.T) {
	// Test the specific case mentioned in the bug: vz and krunkit cannot run foreign architecture
	// so newConf falls back to qemu but network address should still be handled correctly

	ctx := context.Background()

	// Test with amd64 (foreign arch on arm mac)
	conf := config.Config{
		Arch:           "amd64", // Foreign architecture
		VMType:         limaconfig.VZ, // This would normally be used but fails for foreign arch
		Network:        config.Network{Address: true},
	}

	l, err := newConf(ctx, conf)
	assert.NoError(t, err)

	// The VM type should fallback to QEMU for foreign architecture
	assert.Equal(t, limaconfig.QEMU, l.VMType)

	// Network address should still be handled properly even though we fell back
	// This tests that the network configuration doesn't break due to the fallback
	assert.NotNil(t, l.Networks)
}
