package pacer

import (
	"testing"
	"time"

	"github.com/livekit/livekit-server/pkg/sfu/bwe"
	"github.com/livekit/protocol/logger"
	"github.com/pion/rtp"
	"go.uber.org/atomic"
)

func TestBasePacerActivityTracking(t *testing.T) {
	// Create a mock bwe for testing
	mockBWE := &mockBWE{}
	base := NewBase(logger.GetLogger(), mockBWE)

	// Create a packet with extensions
	packet := &Packet{
		Header: &rtp.Header{
			SequenceNumber: 1234,
			Timestamp:      5678,
			SSRC:           9012,
		},
		Payload: []byte{1, 2, 3, 4, 5},
		AbsSendTimeExtID: 1,
		TransportWideExtID: 2,
		WriteStream: &mockWriteStream{},
	}

	// Send the packet
	written, err := base.SendPacket(packet)
	if err != nil {
		t.Fatalf("SendPacket failed: %v", err)
	}

	if written == 0 {
		t.Error("Expected non-zero bytes written")
	}

	// Check that lastPacketSentAt was updated
	durationSinceLast := base.TimeSinceLastSentPacket()
	if durationSinceLast < 0 || durationSinceLast > time.Second {
		t.Errorf("TimeSinceLastSentPacket should be recent, got %v", durationSinceLast)
	}
}

