	"testing"
	"time"
)

func TestBatchCompaction(t *testing.T) {
	// Test that Batch compacts sequences correctly
	cmd1 := func() Msg { return nil }
	cmd2 := func() Msg { return nil }

	// Batch with no commands should return nil
	batch := Batch()
	if batch != nil {
		t.Errorf("expected nil for empty batch, got %v", batch)
	}

	// Batch with one command should return that command directly
	batch = Batch(cmd1)
	if batch != cmd1 {
		t.Errorf("expected cmd1 for single command batch, got %v", batch)
	}

	// Batch with multiple commands should return a BatchMsg
	batch = Batch(cmd1, cmd2)
	if batch == nil {
		t.Errorf("expected BatchMsg for multiple command batch, got nil")
	}
}

