func TestSystemManagerRealtimeSubscriptionRace(t *testing.T) {
	// This test verifies that realtime subscription handling is thread-safe
	// and properly synchronizes subscription state

	hub := mock.NewMockHub()
	sm := NewSystemManager(hub)

	// Initialize the system manager
	err := sm.Initialize()
	require.NoError(t, err)

	// Create a mock websocket connection
	wsConn := &ws.WsConn{
		Conn: &mock.MockWsConn{},
	}

	// Add a system with websocket connection
	systemId := "test-system"
	version := semver.MustParse("0.18.9")
	err = sm.AddWebSocketSystem(systemId, version, wsConn)
	require.NoError(t, err)

	// Simulate concurrent subscription operations
	var wg sync.WaitGroup
	numOperations := 100

	// Start multiple goroutines that will add/remove subscriptions
	for i := 0; i < numOperations; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()

			// Simulate subscription request
			event := &core.RealtimeSubscribeRequestEvent{
				Client: &mock.MockRealtimeClient{
					SubscriptionsFunc: func() map[string]core.SubscriptionOptions {
						return map[string]core.SubscriptionOptions{
							"rt_metrics_system_test-system": {
								Query: map[string]string{"system": "test-system"},
							},
						}
					},
				},
			}

			// This should not cause a panic or race condition
			err := sm.onRealtimeSubscribeRequest(event)
			assert.NoError(t, err)
		}(i)
	}

	wg.Wait()

	// Verify that the subscription state is consistent
	assert.Equal(t, 1, len(activeSubscriptions))

	// Clean up
	sm.RemoveSystem(systemId)
