	event := &core.RealtimeSubscribeRequestEvent{
		Client: &mock.MockRealtimeClient{
			SubscriptionsFunc: func() map[string]core.SubscriptionOptions {
				return map[string]core.SubscriptionOptions{
					"rt_metrics_system_system-1": {
						Query: map[string]string{"system": "system-1"},
					},
				}
			},
		},
	}

	err = sm.onRealtimeSubscribeRequest(event)
	assert.NoError(t, err)

	// Should only have subscription for system-1
	assert.Equal(t, 1, len(activeSubscriptions))
