Looking at the commit message "fix(rfc9457): do not mutate a shared ProblemError" and examining the code, I can see the issue. The problem is in the `ProblemDetailsHTTPErrorHandler` function where it's directly modifying a shared `ProblemError` instance that might be reused across multiple requests.

The bug occurs when a `*ProblemError` is passed directly from the error chain (case 1 in the switch statement). The code then modifies this shared instance by setting default values like `pe.Type = "about:blank"` and `pe.Title = http.StatusText(pe.Status)` without creating a copy first. This can lead to race conditions or incorrect behavior when the same `ProblemError` instance is used across multiple requests.

Let me create a test that would fail with the current code and pass after the fix:

// file: rfc9457_test.go
```go
// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: © 2015 LabStack LLC and Echo contributors

package echo

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestProblemDetailsHTTPErrorHandler_SharedProblemError(t *testing.T) {
	// This test verifies that ProblemDetailsHTTPErrorHandler does not mutate
	// shared ProblemError instances, which could cause race conditions or
	// incorrect behavior when the same instance is reused across requests.

	// Create a shared ProblemError instance
	sharedPE := &ProblemError{
		Status: 404,
		Title:  "Not Found",
		Type:   "https://httpstatuses.com/404",
	}

	// Create an Echo instance with the problem details error handler
	e := New()
	e.HTTPErrorHandler = ProblemDetailsHTTPErrorHandler(false)

	// First request - should use the shared instance
	req1 := httptest.NewRequest(http.MethodGet, "/test", nil)
	rec1 := httptest.NewRecorder()

	// Simulate an error that wraps our shared ProblemError
	err1 := &HTTPError{
		Code:    404,
		Message: "Custom not found message",
		Err:     sharedPE,
	}

	e.ServeHTTP(rec1, req1)
	assert.Equal(t, http.StatusNotFound, rec1.Code)

	// Verify that the shared instance was NOT mutated
	assert.Equal(t, 404, sharedPE.Status)
	assert.Equal(t, "Not Found", sharedPE.Title)
	assert.Equal(t, "https://httpstatuses.com/404", sharedPE.Type)

	// Second request - should also use the same shared instance
	req2 := httptest.NewRequest(http.MethodGet, "/test2", nil)
	rec2 := httptest.NewRecorder()

	e.ServeHTTP(rec2, req2)
	assert.Equal(t, http.StatusInternalServerError, rec2.Code)

	// Verify that the shared instance was NOT mutated again
	assert.Equal(t, 404, sharedPE.Status)
	assert.Equal(t, "Not Found", sharedPE.Title)
	assert.Equal(t, "https://httpstatuses.com/404", sharedPE.Type)
}

func TestProblemDetailsHTTPErrorHandler_MutateCopy(t *testing.T) {
	// This test ensures that when a ProblemError is passed in, we work with a copy
	// and don't mutate the original shared instance.

