)

func TestConfigBuildMissingLevel(t *testing.T) {
	// This test ensures that we validate the Level before opening any sinks.
	// Previously, this would create the log file and then fail with "missing Level".

	// Create a temporary directory for our test
	tempDir, err := os.MkdirTemp("", "zap-config-test")
	require.NoError(t, err)
	defer os.RemoveAll(tempDir)

	// Create a path to a log file that we expect to NOT be created
	logFile := filepath.Join(tempDir, "test.log")

	// Create a config without a level - this should fail immediately
	// without creating any files
	cfg := Config{
		Encoding:         "json",
		OutputPaths:      []string{logFile},
		ErrorOutputPaths: []string{"stderr"},
	}

	logger, err := cfg.Build()
	assert.Error(t, err)
	assert.Nil(t, logger)
	assert.EqualError(t, err, "missing Level")

	// Verify that the log file was never created
	_, err = os.Stat(logFile)
	assert.True(t, os.IsNotExist(err), "Log file should not have been created")
}

func TestConfigBuildValidLevel(t *testing.T) {
