			input:    "foo=bar; Max-Age=0",
			expected: "foo=bar; Max-Age=0",
		},
		{
			name:     "Max-Age positive",
			input:    "foo=bar; Max-Age=3600",
			expected: "foo=bar; Max-Age=3600",
		},
		{
			name:     "Max-Age negative",
			input:    "foo=bar; Max-Age=-1",
			expected: "foo=bar; Max-Age=0",
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			c := AcquireCookie()
			defer ReleaseCookie(c)

			err := c.Parse(tc.input)
			if err != nil {
				t.Fatalf("Unexpected error: %v", err)
			}

			// Check that MaxAge is correctly parsed
			cookieStr := c.String()

			// For negative values, it should be serialized as Max-Age=0
			if tc.name == "Max-Age negative" {
				if !contains(cookieStr, "Max-Age=0") {
					t.Errorf("Expected 'Max-Age=0' for negative value, got: %s", cookieStr)
				}
			} else if tc.name == "Max-Age zero" {
				// For zero values, it should be preserved
				if !contains(cookieStr, "Max-Age=0") {
					t.Errorf("Expected 'Max-Age=0' for zero value, got: %s", cookieStr)
				}
			} else {
				// For positive values, check the expected string
				if !contains(cookieStr, tc.expected) {
					t.Errorf("Expected '%s', got: %s", tc.expected, cookieStr)
				}
			}
		})
	}
}

func TestCookieMaxAgeZeroRoundTrip(t *testing.T) {
	t.Parallel()

	// Test that Max-Age=0 survives a round trip
	original := "sessionid=abc123; Path=/; Max-Age=0; HttpOnly"

	c := AcquireCookie()
	defer ReleaseCookie(c)

	err := c.Parse(original)
	if err != nil {
		t.Fatalf("Unexpected error: %v", err)
	}

	if c.MaxAge() != 0 {
		t.Errorf("Expected MaxAge=0, got %d", c.MaxAge())
	}

	// Serialize back
	serialized := c.String()

	// Parse again to make sure it's valid
	c2 := AcquireCookie()
	defer ReleaseCookie(c2)

	err = c2.Parse(serialized)
	if err != nil {
		t.Fatalf("Unexpected error when parsing serialized cookie: %v", err)
	}

	if c2.MaxAge() != 0 {
		t.Errorf("Expected MaxAge=0 after round trip, got %d", c2.MaxAge())
	}
}

func TestCookieZeroMaxAgeWithExpire(t *testing.T) {
	t.Parallel()

	// Test that Max-Age=0 works with expire time
	expireTime := time.Date(2023, 1, 1, 12, 0, 0, 0, time.UTC)
	_ = expireTime

	c := AcquireCookie()
	defer ReleaseCookie(c)

	err := c.Parse("foo=bar; Max-Age=0; Expires=Wed, 01 Jan 2023 12:00:00 GMT")
	if err != nil {
		t.Fatalf("Unexpected error: %v", err)
	}

	if c.MaxAge() != 0 {
		t.Errorf("Expected MaxAge=0, got %d", c.MaxAge())
	}

	// The serialized cookie should contain Max-Age=0
	cookieStr := c.String()
	if !contains(cookieStr, "Max-Age=0") {
		t.Errorf("Expected serialized cookie to contain 'Max-Age=0', got: %s", cookieStr)
	}
